        this.descendantsApi.figures(sheetId),
      ]);
      this.claims.set(claims);
      this.lastSettleBatch.set(lastBatch);
      this.bulkSettled.set(result);
    } catch {
      this.bulkSettled.set({ settled: 0, refused: this.selected().size });
    } finally {
      this.settling = false;
    }
  }
